def transform(grid):
    """Extend diagonal pairs outward from the center of the marked pattern."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    out = [row[:] for row in grid]
    if not pts:
        return out
    cr = sum(r for r, c in pts) / len(pts)
    cc = sum(c for r, c in pts) / len(pts)
    pair_info = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, rc = r + dr, c + dc
                if 0 <= rr < h and 0 <= rc < w and grid[rr][rc] == color:
                    pair_info.append((color, (r + rr) / 2))
    pair_colors = sorted(set(color for color, _ in pair_info))
    # When the figure contains four separate diagonal color-pairs arranged
    # as two upper pairs over two lower pairs, extend its upper pair rays.
    allowed = None
    if len(pair_colors) == 4:
        avgs = {color: sum(row for col, row in pair_info if col == color) /
                        sum(1 for col, _ in pair_info if col == color)
                for color in pair_colors}
        allowed = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (allowed is not None and color not in allowed):
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, rc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= rc < w and grid[rr][rc] == color):
                    continue
                # Continue from the pair endpoint farther from the pattern center,
                # along the diagonal direction pointing away from that center.
                d1 = (r - cr) ** 2 + (c - cc) ** 2
                d2 = (rr - cr) ** 2 + (rc - cc) ** 2
                if d1 >= d2:
                    y, x = r, c
                    sr, sc = -dr, -dc
                else:
                    y, x = rr, rc
                    sr, sc = dr, dc
                y += sr
                x += sc
                while 0 <= y < h and 0 <= x < w and out[y][x] == bg:
                    out[y][x] = color
                    y += sr
                    x += sc
    return out
